const zones = Object.values(ZONES);
const selectedZoneData = computed<Zone>(() => {
    return ZONES[selectedZone.value] ?? ZONES.cajamarca;
});

function selectZone(key: string): void {
    if (!ZONES[key]) {
        return;
    }
    selectedZone.value = key;
}

function isProvinceActive(key: string): boolean {
    return selectedZone.value === key;
}
