            <!-- =====================================================
           COLUMNA 3 — ZONAS
      ====================================================== -->

            <div class="ori-zones-col">
                <button v-for="zone in zones" :key="zone.key" type="button" class="ori-zone-item" :class="{
                    active: selectedZone === zone.key,
                }" @click="selectZone(zone.key)">
                    <div class="ozi-name">
                        {{ zone.name }}
                    </div>

                    <div class="ozi-alt">
                        {{ zone.alt.label }}
                    </div>
                </button>
            </div>

            <div class="ori-detail-col">
                <!-- FOTO -->

                <div class="ori-photo" :key="selectedZoneData.photo" :style="{
                    backgroundImage: `url('${selectedZoneData.photo}')`,
                }"></div>

                <!-- CARD -->

                <div class="ori-card" :key="selectedZone">
                    <div class="ori-card-name">
                        {{ selectedZoneData.name.toUpperCase() }}
                    </div>

                    <!-- ALTITUDE -->

                    <div class="ori-row">
                        <span class="ori-key"> Altitude </span>

                        <span class="ori-val">
                            {{ selectedZoneData.alt.label }}
                        </span>

                        <div class="alt-bar">
                            <div class="alt-fill" :style="{
                                width: `${selectedZoneData.alt.pct}%`,
                            }" />
                        </div>
                    </div>

                    <!-- VARIETIES -->

                    <div class="ori-row">
                        <span class="ori-key"> Varieties </span>

                        <div class="ori-tags">
                            <span v-for="variety in selectedZoneData.varieties" :key="variety" class="ori-tag g">
                                {{ variety }}
                            </span>
                        </div>
                    </div>

                    <!-- PROCESS -->

                    <div class="ori-row">
